setInterval(poll,4500);
boot();
function localReviewPanel(review){if(!review)return'<div class="notice">节点确认停止后，这里会显示本机工作区和改动摘要。</div>';const files=Array.isArray(review.files)?review.files:[];return `<section class="callout"><div class="split-title"><b>本机工作区</b><div class="actions"><button class="small" data-copy-review-path>复制路径</button>${cursorFileUrl(review.worktreePath)?`<a class="small" href="${escapeHTML(cursorFileUrl(review.worktreePath))}">在 Cursor 打开</a>`:''}</div></div><code>${escapeHTML(review.worktreePath||'')}</code><p class="tiny">任务改动留在本机独立工作区。请在 Cursor 检查文件和 diff，再手动决定如何集成。</p><div class="panelhead"><h3>变更文件</h3>${review.filesTruncated?'<span class="tiny">列表已截断</span>':''}</div>${files.length?`<ul class="review-files">${files.map(file=>`<li><span>${escapeHTML(({added:'新增',modified:'修改',deleted:'删除',renamed:'重命名',untracked:'未跟踪'})[file.status]||file.status||'变更')}</span> <a href="${escapeHTML(cursorFileUrl(file.path)||'#')}" ${cursorFileUrl(file.path)?'':'aria-disabled="true"'}>${escapeHTML(file.path||'')}</a></li>`).join('')}</ul>`:'<div class="tiny">未报告变更文件。</div>'}<div class="panelhead"><h3>文本 diff</h3>${review.diffTruncated?'<span class="tiny">内容已截断</span>':''}</div><pre class="review-diff">${escapeHTML(review.diff||'无文本 diff')}</pre></section>`}
